// Secure version of the application with security best practices applied
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// Add security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
    },
  },
}));

// Add request logging
app.use(morgan('combined'));

// Add rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Health endpoint with basic input sanitization
app.get('/health', (req, res) => {
  // Even for health checks, validate query params if any
  const allowedParams = ['verbose'];
  const sanitizedQuery = {};

  Object.keys(req.query).forEach(key => {
    if (allowedParams.includes(key)) {
      sanitizedQuery[key] = req.query[key];
    }
  });

  const response = { 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  };

  if (sanitizedQuery.verbose === 'true') {
    response.uptime = process.uptime();
  }

  res.json(response);
});

// Users endpoint with basic security considerations
app.get('/users', (req, res) => {
  // In a real app, we would implement pagination to prevent data overload
  const page = parseInt(req.query.page) || 1;
  const limit = Math.min(parseInt(req.query.limit) || 10, 50); // Max 50 items per page

  if (page < 1 || limit < 1) {
    return res.status(400).json({ error: 'Invalid pagination parameters' });
  }

  // Mock user data - in reality this should come from a database with proper access controls
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    users: users.slice((page - 1) * limit, page * limit),
    page: page,
    limit: limit,
    total: users.length
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: 'Internal Server Error'
  });
});

// Handle 404s
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found' 
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

