const fs = require('fs');

// Only load dotenv in development/test environments
if (process.env.NODE_ENV !== 'production') {
  // Check if dotenv is available before requiring
  try {
    const dotenv = require('dotenv');
    dotenv.config();
  } catch (error) {
    console.warn('dotenv not available, using environment variables only');
  }
