// Helper function to detect canary tokens
function isCanaryToken(value) {
  if (!value) return false;
  const canaryPatterns = [
    'CANARY-',
    'canary',
    'test-token'
  ];

  return canaryPatterns.some(pattern => 
    value.toString().toUpperCase().includes(pattern.toUpperCase())
  );
}

// Helper function to validate required secrets in production
function validateProductionSecrets(secretsObj, requiredKeys) {
  if (process.env.NODE_ENV === 'production') {
    const missingSecrets = requiredKeys.filter(key => !secretsObj[key]);
    if (missingSecrets.length > 0) {
      throw new Error(`Missing required production secrets: ${missingSecrets.join(', ')}`);
    }

    // Check for canary tokens in production (should never happen)
    const canaryTokens = Object.entries(secretsObj)
      .filter(([key, value]) => isCanaryToken(value))
      .map(([key]) => key);

    if (canaryTokens.length > 0) {
      console.error('SECURITY ALERT: Canary tokens detected in production environment!', {
        tokens: canaryTokens,
        timestamp: new Date().toISOString()
      });
      // In a real scenario, you'd want to send alerts to a monitoring system
    }
  }
}

